export function awsLessonExercises(lesson) {
  return lesson.checks.map(([question, questionMyanmar, answer, answerMyanmar], index) => ({
    _id:`aws-handbook-${lesson.id}-${index+1}`, studyTab:'AWS', chapterId:`aws-chapter-${lesson.id.split('.')[0]}`,
    section:'နားလည်မှု စစ်ဆေးခြင်း', question, questionMyanmar, answer, answerMyanmar,
    sourceReferences:[{ book:awsHandbookSource.title, section:lesson.id, pages:lesson.pages }],
    generated:true,
  }));
}
